exec('\nfrom __future__ import annotations\n\nimport time\nimport warnings\nimport xml.etree.ElementTree as ET\nfrom pathlib import Path\nfrom urllib.parse import quote_plus\nimport datetime as dt\n\nimport numpy as np\nimport pandas as pd\nimport streamlit as st\nimport yfinance as yf\nimport requests\nimport plotly.graph_objects as go\nimport plotly.express as px\n\nfrom sklearn.linear_model import Ridge, ElasticNet, HuberRegressor\nfrom sklearn.ensemble import RandomForestRegressor, ExtraTreesRegressor, GradientBoostingRegressor, VotingRegressor\nfrom sklearn.metrics import mean_squared_error\n\nwarnings.filterwarnings("ignore")\nROOT = Path(__file__).resolve().parents[1]\n\n# ----------------------------\n# USER-FACING DEFINITIONS\n# ----------------------------\nDEFINITIONS = {\n    "GCMSI": "Global Critical Materials Stress Index. It combines abnormal moves in materials, energy, macro, precious metals and market stress into one z-score-style stress gauge.",\n    "Z-score": "A z-score tells you how unusual a move is compared with its recent history. Around 0 = normal. +1 = above-normal stress/up-move. +2 = very unusual high stress/up-move. -1 or -2 = easing/downside pressure.",\n    "Data interval": "The time between price observations. 1d means one daily bar. 5m means one price point every five minutes.",\n    "Lookback period": "How much history is downloaded. For serious ML, daily 5y is better. For terminal monitoring, intraday is faster but shorter and noisier.",\n    "Prediction horizon": "How far ahead the ML target is. Example: 1d interval and horizon 10 means the model predicts roughly the next 10 trading bars. 5m interval and horizon 12 means roughly the next 60 minutes.",\n    "Shock window": "How many bars are used to calculate each material/macro shock before converting it to a z-score. Smaller = faster/noisier. Larger = smoother/slower.",\n    "Confidence": "A normalized signal-strength score based on how large the latest ML prediction is versus historical target volatility. It is not a probability.",\n    "Test correlation": "Out-of-sample correlation between previous predictions and realized future returns. Above 0 means the model had some directional alignment. Near 0 or negative means weak evidence.",\n    "Validation grade": "A simple grade from test correlation, test sample size and confidence. It tells you whether the ML label is usable as research evidence.",\n    "Final ML stance": "A research label generated only from the ML model and validation: BUY WATCH, SELL/RISK WATCH, KEEP/HOLD WATCH, or NO ACTION. It is not investment advice.",\n    "Options": "Options chain tables show calls, puts, volume, open interest and implied volatility. They are used as market-positioning context, not as direct model training features here.",\n    "Futures/proxies": "Some materials have direct futures (for example crude oil, gold, copper). Others use ETFs or company proxies because free direct prices are not always available.",\n}\n\nCONTROL_HELP = {\n    "Asset universe": "Controls which instruments appear in the asset selector: core ETFs, manufacturing stocks, futures/commodity proxies, or all.",\n    "Filter manufacturing countries": "Limits the manufacturing-stock universe to selected countries.",\n    "Assets to predict": "The exact tickers the ML engine will train/predict. Keep this list moderate for speed.",\n    "Refresh/data interval": "Controls data frequency. Use 1d for robust ML; use 5m/15m for fast monitoring.",\n    "Lookback period": "For the \'past 5 years until now\' requirement, choose interval=1d and lookback=5y.",\n    "Model": "AutoBest tries several ML models and chooses the one with best validation score for each ticker.",\n    "Prediction horizon": "How many bars ahead the model forecasts. The app also tells you the estimated valid-until time.",\n    "Shock window": "Controls sensitivity of z-score features. 20 is a good start.",\n    "News terms": "The terms used for GDELT and news searches. Add terms like Iran, Hormuz, gas, LNG, VIX, gold, rare earths.",\n}\n\nEXPOSURE_DEFS = {\n    "copper": "Sensitivity to copper demand/supply and electrification cycle.",\n    "aluminum": "Sensitivity to aluminum, aerospace structures, smelting and energy costs.",\n    "nickel": "Sensitivity to stainless steel, batteries and superalloys.",\n    "steel_chain": "Sensitivity to iron ore, steel, coal and construction/industrial capex.",\n    "battery": "Sensitivity to lithium, cobalt, graphite, nickel and EV/battery supply chains.",\n    "rare_earths": "Sensitivity to permanent magnets, defense electronics, EV motors and export controls.",\n    "energy": "Sensitivity to oil, gas, LNG, power and fuel costs.",\n    "coal": "Sensitivity to thermal/coking coal and power/steel chain.",\n    "uranium": "Sensitivity to nuclear fuel and energy-security themes.",\n    "aerospace": "Sensitivity to aerospace production and materials like titanium/aluminum/nickel.",\n    "defense": "Sensitivity to defense spending, procurement and strategic materials.",\n    "semiconductor": "Sensitivity to chips, electronics materials and Taiwan/China risk.",\n    "additive_manufacturing": "Sensitivity to 3D printing, digital manufacturing and industrial capex.",\n    "china_sensitivity": "Sensitivity to China demand, export restrictions and China macro/geopolitics.",\n    "geopolitical_sensitivity": "Sensitivity to sanctions, wars, shipping disruptions and strategic policy.",\n    "macro_beta": "General sensitivity to macro/risk appetite."\n}\n\nFUTURES_UNIVERSE = {\n    "Crude Oil WTI Future": "CL=F",\n    "Brent Oil Future": "BZ=F",\n    "Natural Gas Future": "NG=F",\n    "Copper Future": "HG=F",\n    "Gold Future": "GC=F",\n    "Silver Future": "SI=F",\n    "Platinum Future": "PL=F",\n    "Palladium Future": "PA=F",\n    "Iron Ore Future / proxy": "TIO=F",\n    "US Dollar Index": "DX-Y.NYB",\n    "VIX Volatility Index": "^VIX",\n    "US 10Y Yield": "^TNX",\n    "US 13W Yield": "^IRX",\n    "Gold ETF": "GLD",\n    "Silver ETF": "SLV",\n    "Oil ETF": "USO",\n    "Natural Gas ETF": "UNG",\n    "Uranium ETF": "URA",\n    "Rare Earth ETF": "REMX",\n    "Lithium/Battery ETF": "LIT",\n    "Steel ETF": "SLX",\n}\n\n# ----------------------------\n# LOADERS\n# ----------------------------\ndef load_yaml(path: str, fallback: dict):\n    try:\n        import yaml\n        p = ROOT / path\n        if p.exists():\n            return yaml.safe_load(p.read_text(encoding="utf-8")) or fallback\n    except Exception:\n        pass\n    return fallback\n\ndef load_csv(path: str, fallback: pd.DataFrame) -> pd.DataFrame:\n    p = ROOT / path\n    try:\n        if p.exists():\n            return pd.read_csv(p).drop_duplicates()\n    except Exception:\n        pass\n    return fallback\n\ndef fallback_exposure():\n    return pd.DataFrame({\n        "asset": ["XME","COPX","ITA","XAR","PRNT","SPY"],\n        "full_name": ["Mining ETF","Copper miners ETF","Defense ETF","Aerospace ETF","3D Printing ETF","S&P 500 ETF"],\n        "theme": ["Mining","Copper","Defense","Aerospace","AM","Market"],\n        "region": ["USA","Global","USA","USA","Global","USA"],\n    })\n\nmaterials_cfg = load_yaml("config/materials_universe.yml", {"materials": {}}).get("materials", {})\nindices_cfg = load_yaml("config/global_index_config.yml", {"indices": {}}).get("indices", {})\nmacro_cfg = load_yaml("config/macro_series_config.yml", {"macro_proxies": {}}).get("macro_proxies", {})\ngeo_cfg = load_yaml("config/geopolitical_keywords.yml", {"themes": {}, "default_terms": ["critical minerals","rare earth","war","Iran","oil","gas","gold","silver"]})\nnews_sources = load_yaml("config/news_sources.yml", {"rss_sources": {}}).get("rss_sources", {})\nexposure = load_csv("data/exposure_score_table.csv", fallback_exposure())\ncompany_universe = load_csv("data/manufacturing_company_universe.csv", pd.DataFrame())\n\ndef material_tickers(materials):\n    out = []\n    for spec in materials.values():\n        ticks = spec.get("tickers", [spec.get("ticker")]) if isinstance(spec, dict) else [str(spec)]\n        out += [t for t in ticks if t]\n    return out\n\ndef flatten_indices(idx):\n    rows = []\n    for region, mp in idx.items():\n        if isinstance(mp, dict):\n            for name, ticker in mp.items():\n                rows.append({"region": region, "name": name, "ticker": ticker})\n    return pd.DataFrame(rows)\n\ndef safe_period(interval: str, period: str) -> str:\n    # Yahoo/yfinance intraday data is shorter than daily data.\n    if interval == "1m":\n        return period if period in ["1d","5d"] else "5d"\n    if interval in ["2m","5m","15m","30m","60m","90m"]:\n        return period if period in ["1d","5d","1mo"] else "1mo"\n    return period\n\ndef interval_to_timedelta(interval: str, horizon: int):\n    if interval.endswith("m"):\n        return dt.timedelta(minutes=int(interval[:-1]) * horizon)\n    if interval.endswith("h"):\n        return dt.timedelta(hours=int(interval[:-1]) * horizon)\n    if interval == "1d":\n        return dt.timedelta(days=horizon)\n    if interval == "5d":\n        return dt.timedelta(days=5*horizon)\n    return dt.timedelta(days=horizon)\n\ndef estimate_valid_until(last_index, interval: str, horizon: int):\n    try:\n        ts = pd.Timestamp(last_index)\n        return ts + interval_to_timedelta(interval, horizon)\n    except Exception:\n        return None\n\n@st.cache_data(ttl=20, show_spinner=False)\ndef download_prices(tickers, period, interval):\n    tickers = sorted(set([t for t in tickers if isinstance(t, str) and t.strip()]))\n    if not tickers:\n        return pd.DataFrame()\n    raw = yf.download(tickers, period=period, interval=interval, auto_adjust=True, progress=False, threads=False)\n    if raw.empty:\n        return pd.DataFrame()\n    if isinstance(raw.columns, pd.MultiIndex):\n        if "Close" in raw.columns.get_level_values(0):\n            pxs = raw["Close"].copy()\n        else:\n            pxs = raw.xs("Close", axis=1, level=1, drop_level=True).copy()\n    else:\n        pxs = raw[["Close"]].copy()\n        if len(tickers) == 1:\n            pxs.columns = tickers\n    return pxs.dropna(axis=1, how="all").ffill().dropna(how="all")\n\ndef resolve_materials(prices, materials):\n    resolved, rows = {}, []\n    for name, spec in materials.items():\n        ticks = spec.get("tickers", [spec.get("ticker")]) if isinstance(spec, dict) else [str(spec)]\n        selected = next((t for t in ticks if t in prices.columns), None)\n        if selected:\n            resolved[name] = selected\n        rows.append({\n            "material": name,\n            "long_name": spec.get("long_name", name) if isinstance(spec, dict) else name,\n            "selected_ticker": selected or "MISSING",\n            "candidate_tickers": ", ".join([str(t) for t in ticks if t]),\n            "family": spec.get("family", "") if isinstance(spec, dict) else "",\n            "role": spec.get("role", "") if isinstance(spec, dict) else "",\n            "proxy_quality": spec.get("proxy_quality", "") if isinstance(spec, dict) else "",\n            "weight": spec.get("weight", .03) if isinstance(spec, dict) else .03,\n        })\n    return resolved, pd.DataFrame(rows)\n\ndef zscore(s, window):\n    mean = s.rolling(window, min_periods=max(4, window // 3)).mean()\n    std = s.rolling(window, min_periods=max(4, window // 3)).std()\n    return (s - mean) / std\n\ndef build_features(prices, materials, macro, shock_window):\n    resolved, proxy_table = resolve_materials(prices, materials)\n    f = pd.DataFrame(index=prices.index)\n    meta = []\n\n    for name, ticker in resolved.items():\n        spec = materials.get(name, {})\n        col = f"MAT:{name}"\n        f[col] = zscore(prices[ticker].pct_change(shock_window), max(10, shock_window * 3))\n        meta.append({\n            "feature": col,\n            "long_name": spec.get("long_name", name),\n            "ticker": ticker,\n            "family": spec.get("family", "material"),\n            "weight": float(spec.get("weight", .03)),\n            "definition": spec.get("role", "")\n        })\n\n    for name, val in macro.items():\n        ticker = val.get("ticker", val) if isinstance(val, dict) else val\n        if ticker in prices.columns:\n            col = f"MACRO:{name}"\n            f[col] = zscore(prices[ticker].pct_change(shock_window), max(10, shock_window * 3))\n            meta.append({\n                "feature": col,\n                "long_name": name,\n                "ticker": ticker,\n                "family": "macro",\n                "weight": .04,\n                "definition": "macro / market stress proxy"\n            })\n\n    if f.empty:\n        return f, pd.DataFrame(meta), proxy_table\n\n    meta_df = pd.DataFrame(meta)\n    weighted, denom = [], 0\n    for _, r in meta_df.iterrows():\n        weighted.append(f[r["feature"]] * float(r["weight"]))\n        denom += float(r["weight"])\n    f["GCMSI"] = sum(weighted) / denom if denom else f.mean(axis=1)\n\n    for fam in sorted(meta_df["family"].dropna().unique()):\n        cols = meta_df.loc[meta_df["family"] == fam, "feature"].tolist()\n        if cols:\n            f[f"FAMILY:{fam}"] = f[cols].mean(axis=1)\n\n    if "MACRO:VIX" in f.columns:\n        f["REGIME:RiskOff"] = (f["GCMSI"] + f["MACRO:VIX"]) / 2\n    if "MACRO:USDIndex" in f.columns:\n        f["REGIME:USDPressure"] = (f["GCMSI"] + f["MACRO:USDIndex"]) / 2\n\n    return f.replace([np.inf, -np.inf], np.nan).dropna(), meta_df, proxy_table\n\n# ----------------------------\n# PLOTS + EXPLAINERS\n# ----------------------------\ndef plot_lines(df, title, ytitle="Value", normalize=False):\n    if df.empty:\n        st.warning("No data for this chart.")\n        return\n    x = df.copy().ffill().dropna(how="all")\n    if normalize and len(x):\n        x = x / x.iloc[0]\n    fig = go.Figure()\n    for col in x.columns:\n        fig.add_trace(go.Scatter(\n            x=x.index, y=x[col], mode="lines", name=str(col),\n            hovertemplate=f"{col}<br>%{{x}}<br>%{{y:.4f}}<extra></extra>"\n        ))\n    fig.update_layout(\n        title=title, xaxis_title="Time", yaxis_title=ytitle,\n        legend_title="Ticker / signal", hovermode="x unified", height=460\n    )\n    st.plotly_chart(fig, use_container_width=True)\n\ndef plot_bar(series, title):\n    if series.empty:\n        st.warning("No data for this bar chart.")\n        return\n    s = series.dropna().sort_values()\n    fig = px.bar(x=s.values, y=s.index, orientation="h", title=title, labels={"x": "Value", "y": "Element / signal"})\n    fig.update_layout(height=max(420, 25 * len(s)))\n    st.plotly_chart(fig, use_container_width=True)\n\ndef explain_box(title, bullets):\n    with st.expander(f"How to read this: {title}", expanded=True):\n        for b in bullets:\n            st.markdown(f"- {b}")\n\n# ----------------------------\n# NEWS\n# ----------------------------\n@st.cache_data(ttl=240, show_spinner=False)\ndef gdelt(query, max_records):\n    try:\n        r = requests.get(\n            "https://api.gdeltproject.org/api/v2/doc/doc",\n            params={"query": query, "mode": "ArtList", "format": "json", "maxrecords": max_records, "sort": "HybridRel"},\n            timeout=12\n        )\n        if r.status_code != 200:\n            return pd.DataFrame()\n        return pd.DataFrame([{\n            "title": a.get("title", ""),\n            "source": "GDELT / " + a.get("domain", ""),\n            "country": a.get("sourceCountry", ""),\n            "date": a.get("seendate", ""),\n            "url": a.get("url", ""),\n            "source_type": "GDELT search"\n        } for a in r.json().get("articles", [])])\n    except Exception:\n        return pd.DataFrame()\n\n@st.cache_data(ttl=900, show_spinner=False)\ndef rss_fetch(sources, max_per=10):\n    rows, status = [], []\n    for name, spec in sources.items():\n        url = spec.get("url", "") if isinstance(spec, dict) else str(spec)\n        focus = spec.get("focus", "") if isinstance(spec, dict) else ""\n        count = 0\n        ok = False\n        try:\n            r = requests.get(url, timeout=10, headers={"User-Agent": "MatQuantLab/1.0"})\n            if r.status_code == 200:\n                root = ET.fromstring(r.content)\n                items = root.findall(".//item")[:max_per]\n                count = len(items)\n                ok = True\n                for it in items:\n                    rows.append({\n                        "title": (it.findtext("title") or "").strip(),\n                        "source": name,\n                        "country": "",\n                        "date": (it.findtext("pubDate") or "").strip(),\n                        "url": (it.findtext("link") or "").strip(),\n                        "focus": focus,\n                        "source_type": "RSS feed"\n                    })\n        except Exception:\n            ok = False\n        status.append({"source": name, "url": url, "focus": focus, "ok": ok, "articles_loaded": count})\n    return pd.DataFrame(rows), pd.DataFrame(status)\n\n@st.cache_data(ttl=600, show_spinner=False)\ndef google_news_rss(query, max_records=30):\n    try:\n        url = "https://news.google.com/rss/search?q=" + quote_plus(query) + "&hl=en-US&gl=US&ceid=US:en"\n        r = requests.get(url, timeout=10, headers={"User-Agent": "MatQuantLab/1.0"})\n        if r.status_code != 200:\n            return pd.DataFrame()\n        root = ET.fromstring(r.content)\n        rows = []\n        for it in root.findall(".//item")[:max_records]:\n            rows.append({\n                "title": (it.findtext("title") or "").strip(),\n                "source": "Google News RSS",\n                "country": "",\n                "date": (it.findtext("pubDate") or "").strip(),\n                "url": (it.findtext("link") or "").strip(),\n                "focus": "query-based Google News RSS",\n                "source_type": "Google News RSS"\n            })\n        return pd.DataFrame(rows)\n    except Exception:\n        return pd.DataFrame()\n\ndef score_news(news, geo_cfg):\n    if news.empty:\n        return 0.0, pd.DataFrame()\n    titles = " ".join(news["title"].fillna("").astype(str)).lower()\n    rows, score = [], 0\n    for theme, spec in geo_cfg.get("themes", {}).items():\n        words = spec.get("words", []) if isinstance(spec, dict) else spec\n        weight = float(spec.get("weight", 1)) if isinstance(spec, dict) else 1\n        long_name = spec.get("long_name", theme) if isinstance(spec, dict) else theme\n        count = sum(titles.count(str(w).lower()) for w in words)\n        rows.append({"theme": theme, "long_name": long_name, "mentions": count, "weighted_score": count * weight})\n        score += count * weight\n    return min(score / 14, 4.0), pd.DataFrame(rows).sort_values("weighted_score", ascending=False)\n\n# ----------------------------\n# ML\n# ----------------------------\ndef model_candidates():\n    return {\n        "Ridge": Ridge(alpha=8),\n        "ElasticNet": ElasticNet(alpha=.01, l1_ratio=.2, random_state=42),\n        "Huber": HuberRegressor(epsilon=1.35, alpha=.0001),\n        "RandomForest": RandomForestRegressor(n_estimators=180, max_depth=5, random_state=42),\n        "ExtraTrees": ExtraTreesRegressor(n_estimators=220, max_depth=5, random_state=42),\n        "GradientBoosting": GradientBoostingRegressor(random_state=42, max_depth=3),\n        "Ensemble": VotingRegressor([\n            ("ridge", Ridge(alpha=8)),\n            ("rf", RandomForestRegressor(n_estimators=120, max_depth=4, random_state=42)),\n            ("gb", GradientBoostingRegressor(random_state=42, max_depth=2)),\n        ])\n    }\n\ndef get_model(name):\n    if name == "AutoBest":\n        return None\n    return model_candidates().get(name, Ridge(alpha=8))\n\ndef fit_eval_model(model, Xtr, ytr, Xte, yte):\n    model.fit(Xtr, ytr)\n    pred = model.predict(Xte)\n    corr = pd.Series(pred).corr(pd.Series(yte.values))\n    corr = 0 if pd.isna(corr) else float(corr)\n    rmse = float(mean_squared_error(yte, pred) ** .5)\n    vol = max(float(ytr.std()), 1e-6)\n    score = corr - 0.10 * min(rmse / vol, 5)\n    return model, pred, corr, rmse, score\n\ndef feature_importance(model, feat_cols):\n    if hasattr(model, "feature_importances_"):\n        return pd.Series(model.feature_importances_, index=feat_cols).sort_values(ascending=False)\n    if hasattr(model, "coef_"):\n        coef = np.array(model.coef_).reshape(-1)\n        return pd.Series(np.abs(coef), index=feat_cols[:len(coef)]).sort_values(ascending=False)\n    # VotingRegressor: average available importances/coefs from sub-models\n    if hasattr(model, "estimators_"):\n        parts = []\n        for est in model.estimators_:\n            if hasattr(est, "feature_importances_"):\n                parts.append(pd.Series(est.feature_importances_, index=feat_cols))\n            elif hasattr(est, "coef_"):\n                coef = np.array(est.coef_).reshape(-1)\n                parts.append(pd.Series(np.abs(coef), index=feat_cols[:len(coef)]))\n        if parts:\n            return pd.concat(parts, axis=1).mean(axis=1).sort_values(ascending=False)\n    return pd.Series(0, index=feat_cols)\n\ndef validation_grade(confidence, corr, test_rows):\n    if test_rows < 5:\n        return "Weak: too few test rows"\n    if corr > .10 and confidence > .50:\n        return "Good"\n    if corr > .03 and confidence > .33:\n        return "Acceptable"\n    if corr > 0:\n        return "Weak but positive"\n    return "Weak / negative"\n\ndef final_ml_stance(signal, confidence, test_corr, test_rows):\n    grade = validation_grade(confidence, test_corr, test_rows)\n    goodish = grade in ["Good", "Acceptable"]\n    if signal == "Bullish" and confidence >= .60 and goodish:\n        return "ML-only BUY WATCH"\n    if signal == "Bearish" and confidence >= .60 and goodish:\n        return "ML-only SELL / RISK WATCH"\n    if signal == "Bullish" and confidence >= .33 and test_corr > -0.02:\n        return "ML-only BULLISH / KEEP WATCH"\n    if signal == "Bearish" and confidence >= .33 and test_corr > -0.02:\n        return "ML-only BEARISH / PROTECT WATCH"\n    if abs(test_corr) < .03 or confidence < .25:\n        return "ML-only KEEP / NO ACTION"\n    return "ML-only NO ACTION"\n\ndef train_one(asset, prices, features, requested_horizon, model_name, feat_cols, interval):\n    if asset not in prices.columns:\n        return None, None, "no price"\n\n    available_rows = int(prices[asset].dropna().shape[0])\n    effective_horizon = max(1, min(int(requested_horizon), max(1, available_rows // 8)))\n\n    def make_dataset(h):\n        y = prices[asset].pct_change(h).shift(-h).rename("future_return")\n        return pd.concat([features[feat_cols], y], axis=1, join="inner").dropna()\n\n    df = make_dataset(effective_horizon)\n    if len(df) < 35:\n        effective_horizon = max(1, min(5, requested_horizon))\n        df = make_dataset(effective_horizon)\n    if len(df) < 20:\n        effective_horizon = 1\n        df = make_dataset(1)\n    if len(df) < 16:\n        return None, None, "not enough rows"\n\n    split = max(10, int(len(df) * .70))\n    if split >= len(df) - 3:\n        split = max(8, len(df) - 5)\n    tr, te = df.iloc[:split], df.iloc[split:]\n    if len(te) < 3:\n        return None, None, "too few test rows"\n\n    Xtr, ytr = tr[feat_cols].fillna(0), tr["future_return"].astype(float)\n    Xte, yte = te[feat_cols].fillna(0), te["future_return"].astype(float)\n\n    if model_name == "AutoBest":\n        best = None\n        errors = []\n        for nm, m in model_candidates().items():\n            try:\n                fitted, pred, corr, rmse, score = fit_eval_model(m, Xtr, ytr, Xte, yte)\n                if best is None or score > best["score"]:\n                    best = {"name": nm, "model": fitted, "pred": pred, "corr": corr, "rmse": rmse, "score": score}\n            except Exception as e:\n                errors.append(str(e))\n        if best is None:\n            return None, None, "all models failed"\n        model = best["model"]\n        pred = best["pred"]\n        corr = best["corr"]\n        rmse = best["rmse"]\n        selected_model = best["name"]\n    else:\n        try:\n            model = get_model(model_name)\n            model, pred, corr, rmse, _ = fit_eval_model(model, Xtr, ytr, Xte, yte)\n            selected_model = model_name\n        except Exception:\n            return None, None, "model failed"\n\n    latest_pred = float(model.predict(features.iloc[[-1]][feat_cols].fillna(0))[0])\n    vol = max(float(ytr.std()), 1e-6)\n    confidence = min(abs(latest_pred) / (vol * 1.25), 1)\n    signal = "Bullish" if latest_pred > 0 else "Bearish"\n    intensity = "Strong" if confidence > .66 else "Moderate" if confidence > .33 else "Weak"\n\n    imp = feature_importance(model, feat_cols)\n    te2 = te.copy()\n    te2["prediction"] = pred\n    te2["position"] = np.where(te2["prediction"] > 0, 1, -1)\n    te2["strategy_return_net"] = te2["position"] * te2["future_return"] - .0005 * pd.Series(te2["position"], index=te2.index).diff().abs().fillna(1)\n    te2["equity_net"] = (1 + te2["strategy_return_net"].fillna(0)).cumprod()\n    dd = float((te2["equity_net"] / te2["equity_net"].cummax() - 1).min())\n\n    first_date = str(pd.Timestamp(df.index[0]))\n    last_date = str(pd.Timestamp(df.index[-1]))\n    last_price_date = prices[asset].dropna().index[-1]\n    valid_until = estimate_valid_until(last_price_date, interval, effective_horizon)\n    valid_until_str = str(valid_until) if valid_until is not None else "next horizon window"\n\n    grade = validation_grade(confidence, corr, len(te))\n    stance = final_ml_stance(signal, confidence, corr, len(te))\n    bull_bear_score = float((1 if signal == "Bullish" else -1) * confidence * max(min(corr + .25, 1), 0))\n\n    d1 = imp.index[0] if len(imp) > 0 else ""\n    d2 = imp.index[1] if len(imp) > 1 else ""\n    d3 = imp.index[2] if len(imp) > 2 else ""\n\n    reason = (\n        f"The selected ML model ({selected_model}) produced a {signal.lower()} future-return estimate "\n        f"over {effective_horizon} {interval} bars. The strongest drivers were {d1}, {d2}, and {d3}."\n    )\n    final_message = (\n        f"{stance}. Valid research window: until approximately {valid_until_str}. "\n        f"Training/evaluation coverage: {first_date} to {last_date}. "\n        f"Validation grade: {grade}; test correlation {corr:.3f}; confidence {confidence:.2f}. "\n        f"{reason} This is an ML-only research label, not financial advice."\n    )\n\n    row = {\n        "asset": asset,\n        "selected_model": selected_model,\n        "signal": signal,\n        "final_ml_stance": stance,\n        "bull_bear_score": bull_bear_score,\n        "intensity": intensity,\n        "prediction": latest_pred,\n        "confidence": confidence,\n        "test_corr": corr,\n        "validation_grade": grade,\n        "rmse": rmse,\n        "max_drawdown_toy": dd,\n        "requested_horizon": requested_horizon,\n        "effective_horizon": effective_horizon,\n        "interval": interval,\n        "valid_until_est": valid_until_str,\n        "data_start": first_date,\n        "data_end": last_date,\n        "train_rows": len(tr),\n        "test_rows": len(te),\n        "driver_1": d1,\n        "driver_2": d2,\n        "driver_3": d3,\n        "ml_reason": reason,\n        "final_message": final_message\n    }\n    return row, te2, None\n\n@st.cache_data(ttl=120, show_spinner=False)\ndef options_chain(ticker, expiry=None):\n    try:\n        tk = yf.Ticker(ticker)\n        expiries = list(tk.options)\n        if not expiries:\n            return expiries, pd.DataFrame(), pd.DataFrame()\n        exp = expiry if expiry in expiries else expiries[0]\n        ch = tk.option_chain(exp)\n        return expiries, ch.calls.copy(), ch.puts.copy()\n    except Exception:\n        return [], pd.DataFrame(), pd.DataFrame()\n\ndef make_query(terms):\n    clean = [x.strip() for x in terms if x.strip()]\n    return "(" + " OR ".join(clean) + ")" if clean else "(critical minerals OR rare earth)"\n\ndef regime(latest, gscore):\n    gc = latest.get("GCMSI", 0)\n    vix = latest.get("MACRO:VIX", 0)\n    usd = latest.get("MACRO:USDIndex", 0)\n    energy = latest.get("FAMILY:energy_inputs", 0)\n    if gscore >= 2.5 and gc > .4:\n        return "Geopolitical materials shock"\n    if gc > 1.2 and vix > .8:\n        return "Risk-off industrial stress"\n    if energy > 1.1:\n        return "Energy / fuel cost shock"\n    if usd > 1.0 and gc > .3:\n        return "USD commodity pressure"\n    if gc > .8:\n        return "Commodity stress"\n    if gc < -.8:\n        return "Stress easing"\n    return "Normal / mixed"\n\ndef exposure_scores(exposure, latest, gscore):\n    mp = {\n        "copper": latest.get("MAT:Copper", 0),\n        "aluminum": latest.get("MAT:Aluminum", 0),\n        "nickel": latest.get("MAT:Nickel", 0),\n        "steel_chain": latest.get("FAMILY:steel_chain", 0),\n        "battery": latest.get("FAMILY:battery_materials", 0),\n        "rare_earths": latest.get("FAMILY:rare_earths", 0),\n        "energy": latest.get("FAMILY:energy_inputs", 0),\n        "coal": latest.get("MAT:CokingCoal", 0) + latest.get("MAT:ThermalCoal", 0),\n        "uranium": latest.get("MAT:Uranium", 0),\n        "aerospace": latest.get("FAMILY:aerospace_defense_materials", 0),\n        "defense": gscore,\n        "semiconductor": latest.get("FAMILY:electronics_metals", 0) + latest.get("FAMILY:rare_earths", 0),\n        "additive_manufacturing": latest.get("GCMSI", 0),\n        "china_sensitivity": latest.get("MACRO:USDCNY", 0),\n        "geopolitical_sensitivity": gscore,\n        "macro_beta": latest.get("FAMILY:macro", 0),\n    }\n    out = []\n    for _, r in exposure.iterrows():\n        score, den = 0, 0\n        for k, v in mp.items():\n            if k in r and pd.notna(r[k]):\n                score += float(r[k]) * float(v)\n                den += abs(float(r[k]))\n        out.append({\n            "asset": r["asset"],\n            "full_name": r.get("full_name", ""),\n            "theme": r.get("theme", ""),\n            "region": r.get("region", ""),\n            "exposure_adjusted_stress": score / den if den else 0\n        })\n    return pd.DataFrame(out).sort_values("exposure_adjusted_stress", ascending=False)\n\n# ----------------------------\n# UI\n# ----------------------------\nst.set_page_config(page_title="MatQuantLab V9 Pro", layout="wide")\nst.title("MatQuantLab V9 — Explained ML Signal Terminal")\nst.caption("Detailed figure explainers, 5-year daily ML mode, AutoBest model selection, futures/commodities split, options, news feeds, and final ML-only stance messages.")\n\nidx_df = flatten_indices(indices_cfg)\nmacro_tickers = {k: (v.get("ticker", v) if isinstance(v, dict) else v) for k, v in macro_cfg.items()}\n\ncore_assets = sorted(set(exposure["asset"].astype(str).tolist() + ["SPY","XME","COPX","ITA","XAR","PRNT","SOXX","XLE","URA","LIT","REMX","SLX","GLD","SLV","USO","UNG"]))\ncompany_assets = sorted(company_universe["ticker"].dropna().astype(str).unique().tolist()) if not company_universe.empty else []\nfuture_assets = sorted(FUTURES_UNIVERSE.values())\nall_assets = sorted(set(core_assets + company_assets + future_assets))\ndefaults = [x for x in ["COPX","XME","ITA","XAR","PRNT","SOXX","URA","LIT","REMX","GLD","SLV","SPY"] if x in all_assets]\n\nwith st.sidebar:\n    st.header("Controls")\n    with st.expander("What these controls do", expanded=True):\n        for k, v in CONTROL_HELP.items():\n            st.markdown(f"**{k}:** {v}")\n\n    asset_mode = st.radio("Asset universe", ["Core ETFs/stocks", "Manufacturing companies", "Commodities/futures/proxies", "Everything"], index=3)\n\n    country_filter = []\n    if not company_universe.empty:\n        countries = sorted(company_universe["country"].dropna().unique().tolist())\n        country_filter = st.multiselect("Filter manufacturing countries", countries, default=[])\n\n    if asset_mode == "Core ETFs/stocks":\n        choices = core_assets\n    elif asset_mode == "Manufacturing companies":\n        choices = company_assets\n    elif asset_mode == "Commodities/futures/proxies":\n        choices = future_assets\n    else:\n        choices = all_assets\n\n    if country_filter and not company_universe.empty:\n        country_tickers = company_universe.loc[company_universe["country"].isin(country_filter), "ticker"].astype(str).tolist()\n        if asset_mode == "Manufacturing companies":\n            choices = sorted(set(country_tickers))\n        elif asset_mode == "Everything":\n            choices = sorted(set(core_assets + future_assets + country_tickers))\n\n    assets = st.multiselect("Assets to predict", choices, default=[x for x in defaults if x in choices][:12])\n    interval = st.selectbox("Refresh / data interval", ["1m","5m","15m","30m","60m","1d"], index=5)\n    period = st.selectbox("Lookback period", ["1d","5d","1mo","3mo","6mo","1y","2y","5y","10y"], index=7)\n    model_name = st.selectbox("Model", ["AutoBest","Ridge","ElasticNet","Huber","RandomForest","ExtraTrees","GradientBoosting","Ensemble"], index=0)\n    horizon = st.slider("Prediction horizon in bars", 1, 120, 10)\n    shock_window = st.slider("Shock window in bars", 3, 100, 20)\n    max_news = st.slider("News items", 10, 150, 80)\n\n    default_terms = geo_cfg.get("default_terms", ["critical minerals","rare earth","war","Iran","oil","gas","gold","silver"])\n    terms = st.multiselect(\n        "Add/remove geopolitical and market terms",\n        sorted(set(default_terms + ["Middle East","Iran","Israel","Red Sea","Houthis","Strait of Hormuz","fuel","gas","LNG","VIX","China","Taiwan","rare earth export controls","semiconductors","uranium","titanium","gold","silver","central bank gold","safe haven","copper","aluminum","lithium","graphite"])),\n        default=default_terms\n    )\n    extra = st.text_input("Extra terms, comma separated", value="")\n    if extra:\n        terms += [x.strip() for x in extra.split(",") if x.strip()]\n\n    auto = st.toggle("Auto-refresh", value=False)\n    seconds = st.selectbox("Auto-refresh seconds", [20,30,60,120,300], index=2)\n    if st.button("Force refresh"):\n        st.cache_data.clear()\n        st.rerun()\n\nif auto:\n    time.sleep(seconds)\n    st.cache_data.clear()\n    st.rerun()\n\nactual_period = safe_period(interval, period)\nquery = make_query(terms)\n\ntickers = sorted(set(\n    assets\n    + material_tickers(materials_cfg)\n    + list(macro_tickers.values())\n    + idx_df.get("ticker", pd.Series(dtype=str)).dropna().tolist()\n    + list(FUTURES_UNIVERSE.values())\n))\n\nprices = download_prices(tickers, actual_period, interval)\nif prices.empty:\n    st.error("No prices downloaded. Try daily interval and 5y lookback.")\n    st.stop()\n\nfeatures, meta, proxy_table = build_features(prices, materials_cfg, macro_tickers, shock_window)\nif features.empty:\n    st.error("No features built. Try daily interval and longer lookback.")\n    st.stop()\n\ngd = gdelt(query, max_news)\nrss, rss_status = rss_fetch(news_sources, max_per=10)\ngoogle_news = google_news_rss(query, max_records=min(max_news, 40))\nnews = pd.concat([x for x in [gd, rss, google_news] if not x.empty], ignore_index=True) if (not gd.empty or not rss.empty or not google_news.empty) else pd.DataFrame()\ngscore, gthemes = score_news(news, geo_cfg)\n\nlatest = features.iloc[-1]\nreg = regime(latest, gscore)\nfeat_cols = [c for c in features.columns if c.startswith(("MAT:","MACRO:","FAMILY:","REGIME:")) or c == "GCMSI"]\n\npred_rows, curves = [], {}\nfor a in assets:\n    row, curve, err = train_one(a, prices, features, horizon, model_name, feat_cols, interval)\n    if row:\n        exp = exposure.loc[exposure["asset"].astype(str) == a]\n        comp = company_universe.loc[company_universe["ticker"].astype(str) == a] if not company_universe.empty else pd.DataFrame()\n        if len(exp):\n            row["full_name"] = exp.iloc[0].get("full_name", "")\n            row["theme"] = exp.iloc[0].get("theme", "")\n            row["country"] = exp.iloc[0].get("region", "")\n            row["industry_group"] = row["theme"]\n        if len(comp):\n            row["full_name"] = comp.iloc[0].get("company", row.get("full_name", ""))\n            row["theme"] = comp.iloc[0].get("material_link", row.get("theme", ""))\n            row["country"] = comp.iloc[0].get("country", row.get("country", ""))\n            row["industry_group"] = comp.iloc[0].get("industry_group", "")\n        if not row.get("full_name"):\n            row["full_name"] = next((k for k, v in FUTURES_UNIVERSE.items() if v == a), a)\n            row["theme"] = "Commodity/future/proxy"\n            row["country"] = "Global"\n            row["industry_group"] = "Futures / macro / commodity"\n        pred_rows.append(row)\n        curves[a] = curve\n\npred = pd.DataFrame(pred_rows).sort_values(["confidence","test_corr"], ascending=[False,False]) if pred_rows else pd.DataFrame()\n\n# KPI row\nc1,c2,c3,c4,c5,c6,c7 = st.columns(7)\nc1.metric("GCMSI", f"{latest.get(\'GCMSI\',0):.2f}", help=DEFINITIONS["GCMSI"])\nc2.metric("Stress regime", reg)\nc3.metric("Geo/news risk", f"{gscore:.2f}")\nc4.metric("Tickers loaded", prices.shape[1])\nc5.metric("Predictions", len(pred))\nc6.metric("Actual period", actual_period)\nc7.metric("Latest bar", str(prices.index[-1])[:16])\nst.info("BUY/SELL wording is ML-only. The app reports research pressure, not financial advice. Use the final stance together with validation grade, drivers, exposure and news context.")\n\ntabs = st.tabs([\n    "Control Guide",\n    "ML Signal Summary",\n    "Detailed Prediction",\n    "Radar + Drivers",\n    "Stocks / Companies",\n    "Commodities & Futures",\n    "Options",\n    "News Terminal",\n    "Exposure Matrix",\n    "Global / Macro",\n    "Raw Data"\n])\n\nwith tabs[0]:\n    st.subheader("Control guide — what changes what?")\n    for k, v in DEFINITIONS.items():\n        st.markdown(f"**{k}:** {v}")\n    st.markdown("### Recommended settings")\n    st.markdown("""\n- **Best ML mode:** `interval = 1d`, `lookback = 5y`, `model = AutoBest`, `horizon = 5–20`.\n- **Fast terminal mode:** `interval = 5m or 15m`, `lookback = 5d or 1mo`, but prediction validation is weaker.\n- **If predictions are weak:** reduce horizon, increase lookback, or use daily data.\n""")\n    st.markdown("### How tabs connect")\n    st.markdown("""\n1. **Radar + Drivers** tells you what materials/macro shocks are unusual.\n2. **ML Signal Summary** converts those features into bullish/bearish research labels.\n3. **Detailed Prediction** explains one asset and its valid-until horizon.\n4. **Exposure Matrix** explains why an asset should care about specific materials.\n5. **News Terminal** checks whether geopolitics agrees with the model.\n6. **Options** checks positioning context.\n""")\n\nwith tabs[1]:\n    st.subheader("ML-only final stance table")\n    explain_box("ML Signal Summary", [\n        "This is the main output table.",\n        "The app trains a separate model for each selected asset.",\n        "The final stance is generated only from the model prediction, confidence and validation.",\n        "The column `data_start` to `data_end` shows the actual history used. With 1d/5y, it covers approximately the last five years until the latest available bar.",\n        "The `valid_until_est` column estimates how long the horizon applies. Example: 1d interval and 10-bar horizon means roughly 10 trading/calendar days ahead.",\n        "Do not use BUY/SELL labels as real trade instructions; they are research categories."\n    ])\n    if pred.empty:\n        st.warning("No predictions. Try interval=1d, lookback=5y, model=AutoBest, horizon=5–20.")\n    else:\n        cols = [\n            "asset","full_name","country","industry_group","selected_model",\n            "final_ml_stance","signal","intensity","bull_bear_score",\n            "prediction","confidence","test_corr","validation_grade",\n            "driver_1","driver_2","driver_3",\n            "effective_horizon","valid_until_est","data_start","data_end","final_message"\n        ]\n        st.dataframe(pred[cols], use_container_width=True)\n        if "final_ml_stance" in pred:\n            stance_counts = pred["final_ml_stance"].value_counts()\n            plot_bar(stance_counts, "Count of ML-only final stances")\n            st.caption("This chart shows how many selected assets fall into each ML-only stance category.")\n\nwith tabs[2]:\n    st.subheader("Detailed prediction explainer")\n    if pred.empty:\n        st.warning("No detailed prediction available.")\n    else:\n        chosen = st.selectbox("Choose asset", pred["asset"].tolist())\n        row = pred[pred["asset"] == chosen].iloc[0]\n        st.markdown(f"## {chosen} — {row.get(\'full_name\',\'\')}")\n        a,b,c,d,e = st.columns(5)\n        a.metric("Final stance", row["final_ml_stance"])\n        b.metric("Signal", row["signal"])\n        c.metric("Confidence", f"{row[\'confidence\']:.2f}")\n        d.metric("Test corr", f"{row[\'test_corr\']:.3f}")\n        e.metric("Valid until", str(row["valid_until_est"])[:16])\n        st.markdown("### Final ML-only message")\n        st.write(row["final_message"])\n        st.markdown("### Why the model says this")\n        st.write(row["ml_reason"])\n        explain_box("Detailed Prediction", [\n            "Prediction is the estimated future return over the effective horizon.",\n            "Confidence tells how large the prediction is compared with historical target volatility.",\n            "Test correlation checks whether past predictions aligned with future returns.",\n            "Drivers are the material/macro features most used by the selected model.",\n            "If validation grade is weak, ignore the BUY/SELL wording."\n        ])\n        if chosen in curves:\n            plot_lines(curves[chosen][["prediction","future_return"]], f"{chosen}: prediction vs realized future return", "return")\n            st.caption("If the two lines often move in the same direction, the model had some historical alignment. If not, treat the signal as weak.")\n            plot_lines(curves[chosen][["equity_net"]], f"{chosen}: toy ML-only net equity curve with simple cost", "equity")\n            st.caption("This is not a real trading backtest. It is only a visual sanity check with a simple transaction-cost placeholder.")\n\nwith tabs[3]:\n    st.subheader("Radar + strongest drivers")\n    radar_cols = [c for c in [\n        "GCMSI","FAMILY:industrial_metals","FAMILY:steel_chain","FAMILY:battery_materials",\n        "FAMILY:rare_earths","FAMILY:aerospace_defense_materials","FAMILY:energy_inputs",\n        "FAMILY:precious_stress","FAMILY:precious_industrial","FAMILY:macro",\n        "REGIME:RiskOff","REGIME:USDPressure"\n    ] if c in features.columns]\n    plot_lines(features[radar_cols], "Global materials / macro stress radar", "z-score stress")\n    explain_box("Radar chart", [\n        "Each line is a material family, macro family or regime feature.",\n        "Positive values mean that family is unusually high versus its own recent history.",\n        "Negative values mean easing or downside pressure.",\n        "GCMSI is the combined stress index.",\n        "A rising energy line can mean fuel/gas pressure; rising rare-earths can mean strategic-minerals pressure."\n    ])\n    drivers = latest[[c for c in features.columns if c.startswith(("MAT:","MACRO:"))]].sort_values(key=lambda s: s.abs(), ascending=False).head(35)\n    plot_bar(drivers, "Current strongest material / macro drivers")\n    explain_box("Driver bar chart", [\n        "Bars to the right are unusually positive/upward stress moves.",\n        "Bars to the left are unusually negative/easing/downside moves.",\n        "The largest absolute bars are the current dominant shocks.",\n        "Drivers feed into the ML model, so compare this chart with driver_1/driver_2/driver_3 in the prediction table."\n    ])\n\nwith tabs[4]:\n    st.subheader("Stocks / global manufacturing companies")\n    st.markdown("This universe separates manufacturing/materials stocks from ETFs and futures.")\n    if company_universe.empty:\n        st.warning("Company universe file missing.")\n    else:\n        cfilter = st.multiselect("Table country filter", sorted(company_universe["country"].dropna().unique().tolist()), default=country_filter)\n        table = company_universe.copy()\n        if cfilter:\n            table = table[table["country"].isin(cfilter)]\n        st.dataframe(table, use_container_width=True)\n        counts = table.groupby("country")["ticker"].count().sort_values(ascending=False)\n        plot_bar(counts, "Manufacturing/material stocks by country in this universe")\n        explain_box("Manufacturing universe", [\n            "These are not all world companies; they are selected liquid or relevant listed proxies.",\n            "The universe covers mining, steel, aerospace, defense, semiconductors, autos, machinery, energy and additive manufacturing.",\n            "Use the country filter in the sidebar to predict only one region or country.",\n            "Some international tickers may fail if Yahoo Finance does not return data for the selected interval/period."\n        ])\n\nwith tabs[5]:\n    st.subheader("Commodities, futures and material proxies")\n    st.markdown("This tab divides direct futures from ETFs/company proxies.")\n    fdf = pd.DataFrame([{"instrument": k, "ticker": v, "downloaded": v in prices.columns} for k, v in FUTURES_UNIVERSE.items()])\n    st.dataframe(fdf, use_container_width=True)\n    downloaded_fut = [t for t in fdf.loc[fdf["downloaded"], "ticker"].tolist() if t in prices.columns]\n    if downloaded_fut:\n        selected_fut = st.multiselect("Futures/proxies to chart", downloaded_fut, default=downloaded_fut[:10])\n        if selected_fut:\n            plot_lines(prices[selected_fut], "Commodity / future / proxy prices", "normalized", normalize=True)\n            st.caption("Normalized chart starts each instrument at 1.0 so different units can be compared.")\n    st.markdown("### Material proxy resolution")\n    st.dataframe(proxy_table, use_container_width=True)\n    explain_box("Commodities and futures", [\n        "Direct futures are used when Yahoo has them, e.g. CL=F for WTI oil, GC=F for gold, HG=F for copper.",\n        "For materials without clean free futures, the app uses ETF/miner/company proxies.",\n        "The `selected_ticker` column tells you exactly what was used for each material.",\n        "Prediction can also be run directly on futures/proxy tickers by choosing the commodities/futures universe in the sidebar."\n    ])\n\nwith tabs[6]:\n    st.subheader("Options positioning")\n    st.markdown("Options are separated from stocks/futures. They are not the core ML target here; they are market-positioning context.")\n    opt_asset = st.selectbox("Options ticker", assets if assets else ["SPY","XME","COPX","ITA","GLD","SLV","USO"])\n    expiries, calls, puts = options_chain(opt_asset)\n    if not expiries:\n        st.warning("No Yahoo options found for this ticker. Try SPY, XME, COPX, ITA, XLE, GLD, SLV, USO.")\n    else:\n        exp = st.selectbox("Expiration date", expiries)\n        expiries, calls, puts = options_chain(opt_asset, exp)\n        cvol = calls["volume"].fillna(0).sum() if not calls.empty else 0\n        pvol = puts["volume"].fillna(0).sum() if not puts.empty else 0\n        coi = calls["openInterest"].fillna(0).sum() if not calls.empty else 0\n        poi = puts["openInterest"].fillna(0).sum() if not puts.empty else 0\n        a,b,c,d = st.columns(4)\n        a.metric("Call volume", int(cvol))\n        b.metric("Put volume", int(pvol))\n        c.metric("Put/Call volume", f"{pvol/max(cvol,1):.2f}")\n        d.metric("Put/Call OI", f"{poi/max(coi,1):.2f}")\n        explain_box("Options metrics", [\n            "Call volume = contracts traded in calls for the selected expiration.",\n            "Put volume = contracts traded in puts.",\n            "Put/Call volume above 1 can mean heavier put activity, but it can also be hedging.",\n            "Open interest shows contracts still open, not just today\'s trading."\n        ])\n        st.markdown("#### Calls")\n        st.dataframe(calls[["contractSymbol","strike","lastPrice","bid","ask","volume","openInterest","impliedVolatility"]].sort_values("openInterest", ascending=False).head(50), use_container_width=True)\n        st.markdown("#### Puts")\n        st.dataframe(puts[["contractSymbol","strike","lastPrice","bid","ask","volume","openInterest","impliedVolatility"]].sort_values("openInterest", ascending=False).head(50), use_container_width=True)\n\nwith tabs[7]:\n    st.subheader("News terminal")\n    st.write(f"Current query: `{query}`")\n    st.metric("Keyword news risk score", f"{gscore:.2f}")\n    st.markdown("### Source status")\n    source_status = pd.DataFrame([\n        {"source": "GDELT search", "ok": not gd.empty, "articles_loaded": len(gd), "focus": "global query-based news"},\n        {"source": "Google News RSS", "ok": not google_news.empty, "articles_loaded": len(google_news), "focus": "query-based news RSS"},\n    ])\n    if not rss_status.empty:\n        source_status = pd.concat([source_status, rss_status[["source","ok","articles_loaded","focus"]]], ignore_index=True)\n    st.dataframe(source_status, use_container_width=True)\n    st.markdown("### Theme intensity")\n    st.dataframe(gthemes, use_container_width=True)\n    if not gthemes.empty:\n        plot_bar(gthemes.set_index("long_name")["weighted_score"], "Geopolitical / macro-news theme intensity")\n    explain_box("News terminal", [\n        "GDELT gives global query-based news matching your selected terms.",\n        "Google News RSS gives another query-based feed.",\n        "RSS feeds, including GCIRD when reachable, provide fixed-source monitoring.",\n        "Changing the sidebar terms changes the GDELT and Google News query.",\n        "The score is keyword-based and should be treated as a monitoring signal, not verified sentiment."\n    ])\n    if news.empty:\n        st.warning("No news returned. Remove some terms or use a simpler query.")\n    else:\n        st.dataframe(news[["title","source","country","date","url"]].head(150), use_container_width=True)\n\nwith tabs[8]:\n    st.subheader("Exposure matrix")\n    st.dataframe(exposure, use_container_width=True)\n    st.markdown("### Exposure column definitions")\n    defs = pd.DataFrame([{"column": k, "meaning": v} for k, v in EXPOSURE_DEFS.items()])\n    st.dataframe(defs, use_container_width=True)\n    sc = exposure_scores(exposure, latest, gscore)\n    st.markdown("### Exposure-adjusted stress ranking")\n    st.dataframe(sc, use_container_width=True)\n    fig = px.bar(sc, x="exposure_adjusted_stress", y="asset", color="theme", orientation="h", title="Exposure-adjusted stress by asset")\n    st.plotly_chart(fig, use_container_width=True)\n    explain_box("Exposure matrix", [\n        "Exposure scores are manually designed material/sector sensitivity weights from 0 to 1.",\n        "The ranking multiplies those exposures by current material/macro/geopolitical stress.",\n        "This is the bridge between metallurgy/materials knowledge and quant finance.",\n        "If an asset has high rare-earth exposure and rare-earth/geopolitical stress rises, its exposure-adjusted stress rises."\n    ])\n\nwith tabs[9]:\n    st.subheader("Global indices and macro")\n    region = st.selectbox("Region", sorted(idx_df["region"].unique()) if not idx_df.empty else [])\n    if region:\n        rts = [t for t in idx_df[idx_df["region"] == region]["ticker"].tolist() if t in prices.columns]\n        if rts:\n            plot_lines(prices[rts], f"{region} index proxies", "normalized", normalize=True)\n            st.caption("This compares regional benchmark direction. It helps separate asset-specific stress from global risk-on/risk-off moves.")\n        else:\n            st.warning("No downloaded tickers for this region.")\n    macro_cols = [c for c in features.columns if c.startswith("MACRO:")]\n    if macro_cols:\n        plot_lines(features[macro_cols], "Macro stress features", "z-score")\n        explain_box("Macro features", [\n            "VIX = equity volatility/risk appetite proxy.",\n            "USD index = dollar pressure; stronger USD often stresses commodities and EM assets.",\n            "Rates and credit proxies help detect financial tightening.",\n            "FX proxies help connect Japan, China and Europe macro stress."\n        ])\n\nwith tabs[10]:\n    st.subheader("Raw data and diagnostics")\n    st.markdown("Use this tab to check what actually downloaded and what the model used.")\n    st.markdown(f"**Requested period:** {period} | **Actual period used:** {actual_period} | **Interval:** {interval}")\n    st.markdown(f"**Price coverage:** {prices.index[0]} to {prices.index[-1]}")\n    st.dataframe(prices.tail(100), use_container_width=True)\n    st.dataframe(features.tail(100), use_container_width=True)\n    st.dataframe(meta, use_container_width=True)\n\nst.divider()\nst.caption("Data: Yahoo Finance via yfinance + GDELT/Google/RSS feeds. Intraday/free data may be delayed or incomplete. ML labels are research outputs, not financial advice.")\n')
